components.script:
// 开门请求处理节点 - 解析参数
openType = flowContext.getData("openType");
openWay = flowContext.getData("openWay");
doorNo = flowContext.getData("doorNo");
userType = flowContext.getData("userType");
doorType = flowContext.getData("doorType");
leaveOpenType = flowContext.getData("leaveOpenType");
leaveFromType = flowContext.getData("leaveFromType");
isSwitch = flowContext.getData("isSwitch");

// 设置默认值
if (openType == null) { openType = 0; }
if (openWay == null) { openWay = 1; }
if (doorNo == null) { doorNo = 1; }
if (userType == null) { userType = 1; }
if (doorType == null) { doorType = 2; }
if (leaveOpenType == null) { leaveOpenType = -1; }
if (leaveFromType == null) { leaveFromType = -1; }
if (isSwitch == null) { isSwitch = false; }

// 映射进出门
way = (openType == 0) ? "enter" : "leave";
flowContext.setData("way", way);
flowContext.setData("doorType", doorType);
flowContext.setData("leaveOpenType", leaveOpenType);
flowContext.setData("leaveFromType", leaveFromType);
flowContext.setData("isSwitch", isSwitch);
flowContext.setData("openDoorTime", java.lang.System.currentTimeMillis());
flowContext.setData("openDoorSuccess", true);

// openWay 映射描述
openWayDesc = "未知";
if (openWay == 0) { openWayDesc = "扫码开门"; }
else if (openWay == 1) { openWayDesc = "购物后离店"; }
else if (openWay == 2) { openWayDesc = "POS离店"; }
else if (openWay == 3) { openWayDesc = "客服开门"; }
else if (openWay == 4) { openWayDesc = "红外感应"; }
else if (openWay == 5) { openWayDesc = "应急按钮"; }
else if (openWay == 6) { openWayDesc = "商家开门"; }
flowContext.setData("openWayDesc", openWayDesc);

// 模拟日志
flowContext.setData("log_openDoor", "开门请求处理完成: way=" + way + ", doorNo=" + doorNo + ", openWay=" + openWay + "(" + openWayDesc + ")");

// 判断是否在值守状态
onWatch = flowContext.getData("onWatch");
if (onWatch == null) { onWatch = false; }
return onWatch;

// 值守中 - 播放开门语音
way = flowContext.getData("way");
userType = flowContext.getData("userType");
doorNo = flowContext.getData("doorNo");
doorType = flowContext.getData("doorType");
leaveOpenType = flowContext.getData("leaveOpenType");
leaveFromType = flowContext.getData("leaveFromType");
isSwitch = flowContext.getData("isSwitch");

// 设置默认值
if (way == null) { way = "enter"; }
if (userType == null) { userType = 1; }
if (doorNo == null) { doorNo = 1; }
if (doorType == null) { doorType = 2; }
if (leaveOpenType == null) { leaveOpenType = -1; }
if (leaveFromType == null) { leaveFromType = -1; }
if (isSwitch == null) { isSwitch = false; }

// 语音文件映射逻辑
voiceFile = null;
voiceFileDesc = "";

if ("enter".equals(way)) {
    // 进门语音
    if (doorType == 2 || leaveOpenType == -1) {
        voiceFile = "default_welcome_voice.mp3";
        voiceFileDesc = "默认欢迎语";
    } else if (leaveOpenType == 1) {
        voiceFile = "push_door_enter.mp3";
        voiceFileDesc = "推门进店";
    } else {
        voiceFile = "pull_door_enter.mp3";
        voiceFileDesc = "拉门进店";
    }
} else {
    // 离店语音
    if (doorType == 2) {
        voiceFile = isSwitch ? "emergency_leave.mp3" : "leave_shop.mp3";
        voiceFileDesc = isSwitch ? "应急离店" : "正常离店";
    } else if (leaveOpenType == 0) {
        voiceFile = isSwitch ? "push_door_emergency.mp3" : "push_door_leave.mp3";
        voiceFileDesc = isSwitch ? "推门应急离店" : "推门离店";
    } else {
        voiceFile = isSwitch ? "pull_door_emergency.mp3" : "pull_door_leave.mp3";
        voiceFileDesc = isSwitch ? "拉门应急离店" : "拉门离店";
    }
}

// userType 描述
userTypeDesc = "未知";
if (userType == 1) { userTypeDesc = "新客"; }
else if (userType == 2) { userTypeDesc = "老客"; }
else if (userType == 3) { userTypeDesc = "老板"; }

// 模拟播放语音
voicePlayed = true;

// 保存结果到上下文
flowContext.setData("voiceFile", voiceFile);
flowContext.setData("voiceFileDesc", voiceFileDesc);
flowContext.setData("userTypeDesc", userTypeDesc);
flowContext.setData("playVoiceTime", java.lang.System.currentTimeMillis());
flowContext.setData("voicePlayed", voicePlayed);
flowContext.setData("log_voice", "播放语音: " + voiceFile + " (" + voiceFileDesc + ")");

// 非值守状态 - 仅打印日志
way = flowContext.getData("way");
openWay = flowContext.getData("openWay");
doorNo = flowContext.getData("doorNo");
doorType = flowContext.getData("doorType");
openWayDesc = flowContext.getData("openWayDesc");

if (way == null) { way = "enter"; }
if (openWay == null) { openWay = 1; }
if (doorNo == null) { doorNo = 1; }
if (doorType == null) { doorType = 2; }
if (openWayDesc == null) { openWayDesc = "未知"; }

flowContext.setData("voicePlayed", false);
flowContext.setData("voiceFile", null);
flowContext.setData("voiceFileDesc", "非值守状态不播放");
flowContext.setData("log_noWatch", "非值守状态，不播放语音。way=" + way + ", doorNo=" + doorNo);

// 结果汇总
way = flowContext.getData("way");
openDoorSuccess = flowContext.getData("openDoorSuccess");
voicePlayed = flowContext.getData("voicePlayed");
onWatch = flowContext.getData("onWatch");
voiceFile = flowContext.getData("voiceFile");
voiceFileDesc = flowContext.getData("voiceFileDesc");
openWayDesc = flowContext.getData("openWayDesc");
userTypeDesc = flowContext.getData("userTypeDesc");
doorType = flowContext.getData("doorType");
isSwitch = flowContext.getData("isSwitch");

if (openDoorSuccess == null) { openDoorSuccess = false; }
if (voicePlayed == null) { voicePlayed = false; }
if (onWatch == null) { onWatch = false; }
if (voiceFile == null) { voiceFile = "无"; }
if (voiceFileDesc == null) { voiceFileDesc = "无"; }
if (openWayDesc == null) { openWayDesc = "未知"; }
if (userTypeDesc == null) { userTypeDesc = "未知"; }
if (doorType == null) { doorType = 2; }
if (isSwitch == null) { isSwitch = false; }

// 门类型描述
doorTypeDesc = (doorType == 1) ? "电磁门" : "电机门";

result = "{" +
    "\"way\":\"" + way + "\"," +
    "\"openDoorSuccess\":" + openDoorSuccess + "," +
    "\"onWatch\":" + onWatch + "," +
    "\"voicePlayed\":" + voicePlayed + "," +
    "\"voiceFile\":\"" + voiceFile + "\"," +
    "\"voiceFileDesc\":\"" + voiceFileDesc + "\"," +
    "\"doorTypeDesc\":\"" + doorTypeDesc + "\"," +
    "\"isSwitch\":" + isSwitch +
"}";
flowContext.setData("result", result);
flowContext.setData("processEndTime", java.lang.System.currentTimeMillis());
